//! FastCDC content-defined variable chunking for delta synchronization.

use crate::crypto::integrity::hash_chunk;
use fastcdc::v2020::{FastCDC, StreamCDC};
use std::io::Read;

/// Variable chunk generated by FastCDC.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FastCdcChunk {
    /// Byte offset in stream
    pub offset: u64,
    /// Chunk length
    pub length: usize,
    /// BLAKE3 checksum
    pub hash: [u8; 32],
}

/// FastCDC chunking wrapper.
pub struct DeltaChunker {
    min_size: u32,
    avg_size: u32,
    max_size: u32,
}

impl DeltaChunker {
    /// Creates a FastCDC chunker with standard 64KB target chunk size.
    pub fn new() -> Self {
        Self {
            min_size: 16 * 1024,
            avg_size: 64 * 1024,
            max_size: 256 * 1024,
        }
    }

    /// Splits an in-memory buffer into variable content-defined chunks.
    pub fn chunk_slice(&self, data: &[u8]) -> Vec<FastCdcChunk> {
        let chunker = FastCDC::new(data, self.min_size, self.avg_size, self.max_size);
        let mut chunks = Vec::new();

        for entry in chunker {
            let slice = &data[entry.offset..entry.offset + entry.length];
            chunks.push(FastCdcChunk {
                offset: entry.offset as u64,
                length: entry.length,
                hash: hash_chunk(slice),
            });
        }
        chunks
    }
}

impl Default for DeltaChunker {
    fn default() -> Self {
        Self::new()
    }
}
